808.docs:
# (ASCII) Bytes to Unsigned.

Parse a `u16` from an ASCII byte slice.

## Examples

```
use dactyl::traits::BytesToUnsigned;

assert_eq!(
    u16::btou(b"0"),
    Some(u16::MIN),
);
assert_eq!(
    u16::btou(b"65535"),
    Some(u16::MAX),
);

// Leading zeroes are fine.
assert_eq!(
    u16::btou(b"00000123"),
    Some(123),
);

// These are all bad.
assert!(u16::btou(&[]).is_none()); // Empty.
assert!(u16::btou(b"+13").is_none()); // Plus.
assert!(u16::btou(b" 2223231  ").is_none()); // Whitespace.
assert!(u16::btou(b"nope").is_none()); // Not a number.
assert!(u16::btou(
    b"4402823669209384634633746074317682114550").is_none()
); // Too big.
```

